  // ─── HTML Blocks (used with data-i18n-html) ──────────────────────
  'help.install_app_html':
    'MUSIXQUARE ગમે છે? તેને ઍપ તરીકે ઇન્સ્ટૉલ કરી શકો છો.<ul class="help-list"><li><strong>iOS:</strong> શેર → હોમ સ્ક્રીન પર ઉમેરો</li><li><strong>Android:</strong> મેનૂ → ઍપ ઇન્સ્ટૉલ કરો</li><li><strong>Windows:</strong> ઍડ્રેસ બારમાં ઇન્સ્ટૉલ ચિહ્ન</li><li><strong>macOS:</strong> શેર → Dock માં ઉમેરો</li></ul>',
  'help.local_recommended_html':
    'એક જ નેટવર્ક પર ઑડિયો શેરિંગ સૌથી સ્થિર હોય છે.<ul class="help-list"><li>દૂરસ્થ સહભાગીઓ પણ એ જ સુવિધાઓ વાપરી શકે છે.</li><li>દૂરસ્થ સહભાગીઓ Cloudflare માર્ગ વાપરે છે, તેથી નેટવર્કની સ્થિતિ પ્રમાણે વિલંબ વધી શકે અથવા ઑડિયો મળવામાં નિષ્ફળતા આવી શકે છે.</li><li>VPN અથવા નિયંત્રિત નેટવર્ક જોડાણને અસ્થિર બનાવી શકે છે.</li></ul>',
  'setup.how_to_connect_html':
    'જોડાવા માટે હોસ્ટનો <strong>6-અંકનો કોડ</strong> દાખલ કરો.<ul class="help-list"><li><strong>હોસ્ટ:</strong> “રૂમ બનાવો” → કોડ તપાસો</li><li><strong>સહભાગી:</strong> “રૂમમાં જોડાઓ” → કોડ દાખલ કરો</li><li><strong>હોસ્ટ સહિત વધુમાં વધુ 100 ડિવાઇસ</strong> જોડાઈ શકે છે.</li></ul>',
  'player.play_speakers_html':
    'દરેક સહભાગી એક <strong>ભૂમિકા (આઉટપુટ ચૅનલ)</strong> પસંદ કરે છે.<ul class="help-list"><li><strong>મધ્ય:</strong> સ્ટીરિયો (મૂળભૂત) આઉટપુટ</li><li><strong>ડાબું:</strong> <bdi dir="ltr">L</bdi> ચૅનલ આઉટપુટ</li><li><strong>જમણું:</strong> <bdi dir="ltr">R</bdi> ચૅનલ આઉટપુટ</li><li><strong>સબવૂફર:</strong> ઓછી આવર્તનનું મિશ્રિત આઉટપુટ</li></ul><strong>સેટિંગ્સ</strong>માં ભૂમિકા ગમે ત્યારે બદલી શકો છો.',
  'player.play_media_action_html':
    'હોસ્ટ પાસે 3 વિકલ્પ છે.<ul class="help-list"><li><strong>સ્થાનિક ફાઇલ લોડ કરો:</strong> તમારા ડિવાઇસમાંથી સંગીત પસંદ કરો. ચોક્કસ સિંક સમર્થિત</li><li><strong>સાથે YouTube:</strong> વિડિયો અને પ્લેલિસ્ટ સમર્થિત. ચૅનલ વિભાજન કે ઑડિયો ઇફેક્ટ નથી</li><li><strong>સિસ્ટમ ઑડિયો શેરિંગ:</strong> હોસ્ટ કમ્પ્યુટર પર Chromium-આધારિત બ્રાઉઝર વાપરે ત્યારે ઉપલબ્ધ</li></ul>',
  'help.need_help_html':
    '<ul class="help-list"><li><strong>કોડ દાખલ કર્યો છતાં જોડાઈ શકાતું નથી:</strong> કોડ તપાસો અને થોડી વારમાં ફરી પ્રયાસ કરો. કંપની, શાળા અથવા VPN નેટવર્ક જોડાણને નિયંત્રિત કરી શકે છે.</li><li><strong>અસ્થિર જોડાણ:</strong> સ્થાનિક સહભાગીઓએ રાઉટરની નજીક રહેવાનો પ્રયાસ કરવો અને દૂરસ્થ સહભાગીઓએ સ્થિર ઇન્ટરનેટ જોડાણ વાપરવું.</li><li><strong>અન્ય સમસ્યાઓ:</strong> નેટવર્કની સ્થિતિ તપાસો અને બધા ડિવાઇસ પર ઍપ ફરી શરૂ કરો. કોઈ પ્રશ્ન હોય તો <a href="/faq" target="_blank" rel="noopener noreferrer" style="color:inherit;text-decoration:underline">FAQ</a> જુઓ અથવા સૌથી નીચે આપેલા ઈમેલથી અમારો સંપર્ક કરો.</li></ul>',
